if (import.meta.hot) {
  let overlay: HTMLElement | null = null;

  import.meta.hot.on('dt:ts-error', (data: { message: string }) => {
    removeOverlay();
    overlay = createOverlay(data.message);
    document.body.appendChild(overlay);
  });

  import.meta.hot.on('dt:ts-errors-clear', () => {
    removeOverlay();
  });

  /** Removes the active error overlay from the DOM. */
  function removeOverlay(): void {
    overlay?.remove();
    overlay = null;
    // Also remove any server-side injected overlays (from transformIndexHtml).
    document
      .querySelectorAll('.dt-error-overlay-container')
      .forEach((el) => el.remove());
  }

  /** Creates and returns a styled error overlay element for the given message. */
  function createOverlay(message: string): HTMLElement {
    const container = document.createElement('div');
    container.className = 'dt-error-overlay-container';
    container.style.cssText = [
      'position:fixed',
      'top:0',
      'left:0',
      'width:100%',
      'height:100%',
      'background:rgba(0,0,0,0.85)',
      'z-index:999999',
      'display:flex',
      'align-items:center',
      'justify-content:center',
      'font-family:monospace',
    ].join(';');

    const box = document.createElement('div');
    box.style.cssText = [
      'background:#1a1a1a',
      'border:2px solid #c20b29',
      'border-radius:4px',
      'padding:24px',
      'max-width:80vw',
      'max-height:80vh',
      'overflow:auto',
      'color:#fff',
    ].join(';');

    const title = document.createElement('p');
    title.style.cssText =
      'color:#c20b29;margin:0 0 12px;font-weight:bold;font-size:14px;';
    title.textContent = 'TypeScript Error';

    const pre = document.createElement('pre');
    pre.className = 'dt-app-error-text';
    pre.style.cssText =
      'margin:0;white-space:pre-wrap;font-size:13px;line-height:1.5;';
    // Strip ANSI escape sequences so terminal color codes don't appear as garbage.
    // eslint-disable-next-line no-control-regex
    pre.textContent = message.replace(/\\x1B\\[[0-9;]*[A-Za-z]/g, '');

    box.appendChild(title);
    box.appendChild(pre);
    container.appendChild(box);
    return container;
  }
}

